-- Kitaplık: R2'deki kitapların listesi
CREATE TABLE IF NOT EXISTS public.books (
  id          bigserial PRIMARY KEY,
  file_key    text NOT NULL UNIQUE,          -- R2'deki dosya yolu
  cover_key   text,                          -- R2'deki kapak resmi yolu
  title       text NOT NULL,
  category    text NOT NULL CHECK (category IN ('konu-anlatimi','soru-bankasi','deneme')),
  branch_id   integer,                       -- NULL = karma (birden çok branş)
  size_bytes  bigint,
  sort_order  integer NOT NULL DEFAULT 0,
  hidden      boolean NOT NULL DEFAULT false,
  created_at  timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.books ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "books_all" ON public.books;
CREATE POLICY "books_all" ON public.books FOR ALL USING (true) WITH CHECK (true);
CREATE INDEX IF NOT EXISTS idx_books_branch ON public.books(branch_id);

-- 163 kitap (birebir aynı 6 kopya gizli = hidden true)
ON CONFLICT (file_key) DO NOTHING;
